pub(super) struct CompactedItemWire<'a> {
    message: Cow<'a, str>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    replacement_history: Option<Vec<Cow<'a, ResponseItem>>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
